-- Tend · .tend/tend.db · schema v1
-- Nothing has shipped yet, so this file is edited in place; migrations start with the first
-- release. Scope: notes, tasks, people, timers, labels. Calendar, events and reminders come later
-- (docs/later/).
--
-- Conventions
--   * every table has `id TEXT PRIMARY KEY`: a ULID generated by the app, never replaced, and
--     never reused (a deleted id stays deleted). A few rows that exist on every device and are
--     never deleted use a fixed id: settings = their key, default statuses = their value,
--     root folders = 'root'. Link rows get a fresh ULID each time they are added; their UNIQUE
--     pair stops duplicates, and sync merges two devices' rows for the same pair.
--   * synced tables have `updated_at` (ms since the Unix epoch, UTC), set by the app on every
--     insert and update (sync keeps the newest; see docs/v1-sync-spec.md)
--   * other moments are INTEGER milliseconds since the Unix epoch, UTC (*_at columns)
--   * local calendar values stay TEXT: dates 'YYYY-MM-DD', times 'HH:MM' (24h)
--   * booleans are INTEGER 0/1; colors are '#rrggbb'
--   * every table is STRICT (SQLite >= 3.37); open with PRAGMA foreign_keys = ON
--   * paths are relative: attachments.path to the vault ('notes/Work/Q4 plan.md',
--     '.attachments/<id>.pdf'); folder paths to their root ('' = root, 'Work', 'Work/Infra').
--     Paths are unique ignoring ASCII case, like the macOS file system
--   * deletes are recorded in `deletions` and every write in `activity`, by the triggers at the end

PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;

-------------------------------------------------------------------------------
-- 0. App identity and version (the "incompatible db" check reads this). Local.
-------------------------------------------------------------------------------
CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
) STRICT;
INSERT INTO meta (key, value) VALUES
  ('app_id', 'tend'),
  ('schema_version', '1'),
  ('created_at', CAST(unixepoch('subsec') * 1000 AS INTEGER));

-- Key/value settings (value is JSON). id = key. Which keys sync is decided by the app.
CREATE TABLE settings (
  id         TEXT PRIMARY KEY,
  key        TEXT NOT NULL UNIQUE,
  value      TEXT NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 1. Tags (shared by notes and tasks)
-------------------------------------------------------------------------------
CREATE TABLE tags (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE COLLATE NOCASE,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 2. Attachments: every file Tend knows, at its place in the vault.
-------------------------------------------------------------------------------
-- A note's body is an attachment under notes/; an attached file lives in .attachments/<id>.<ext>.
-- `mtime` and `missing_at` describe this device's copy of the file and are not synced.
CREATE TABLE attachments (
  id         TEXT PRIMARY KEY,
  path       TEXT NOT NULL UNIQUE COLLATE NOCASE, -- 'notes/Work/Q4 plan.md', '.attachments/<id>.pdf'
  name       TEXT NOT NULL,              -- display / download name: 'invoice march.pdf', 'plan.md'
  mime_type  TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256     TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  mtime      INTEGER NOT NULL DEFAULT 0, -- local: file mtime when last read
  missing_at INTEGER                     -- local: file gone from disk; purged after a grace period
) STRICT;

-- Where an attachment is used (a task, note, comment or person). Linking a note means linking
-- its attachment.
CREATE TABLE attachment_links (
  id            TEXT PRIMARY KEY,
  owner_type    TEXT NOT NULL CHECK (owner_type IN ('task', 'note', 'comment', 'person')),
  owner_id      TEXT NOT NULL,
  attachment_id TEXT NOT NULL REFERENCES attachments(id) ON DELETE CASCADE,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL,
  UNIQUE (owner_type, owner_id, attachment_id)
) STRICT;
CREATE INDEX attachment_links_owner ON attachment_links(owner_type, owner_id);

-------------------------------------------------------------------------------
-- 3. Notes. The body is a markdown file (an attachment under notes/); the note is the record.
-------------------------------------------------------------------------------
-- A note's title is its file name without .md (read from attachments.path), so renaming a note
-- renames its file and a rename outside Tend renames the note. Renaming or moving a note changes
-- only attachments.path; the note's id stays, so tags and links follow it. On vault open and on outside changes the app scans notes/ and
-- matches files to attachments by path.
CREATE TABLE note_folders (
  id         TEXT PRIMARY KEY,
  path       TEXT NOT NULL UNIQUE COLLATE NOCASE, -- '' (= notes/ itself), 'Work', 'Work/Infra'
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  missing_at INTEGER                     -- local: folder gone from disk
) STRICT;
INSERT INTO note_folders (id, path, created_at, updated_at) VALUES
  ('root', '', CAST(unixepoch('subsec') * 1000 AS INTEGER), CAST(unixepoch('subsec') * 1000 AS INTEGER));

CREATE TABLE notes (
  id            TEXT PRIMARY KEY,
  attachment_id TEXT NOT NULL UNIQUE REFERENCES attachments(id) ON DELETE CASCADE,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
) STRICT;

CREATE TABLE note_tags (
  id         TEXT PRIMARY KEY,
  note_id    TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
  tag_id     TEXT NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,
  updated_at INTEGER NOT NULL,
  UNIQUE (note_id, tag_id)
) STRICT;

-------------------------------------------------------------------------------
-- 4. People (own section; birthdays shown in the list, task assignees)
-------------------------------------------------------------------------------
CREATE TABLE people (
  id                TEXT PRIMARY KEY,
  first_name        TEXT NOT NULL,
  last_name         TEXT NOT NULL DEFAULT '',
  nickname          TEXT,                  -- shown instead of first + last when set
  dob_year          INTEGER,               -- optional: birthday known, year unknown
  dob_month         INTEGER CHECK (dob_month BETWEEN 1 AND 12),
  dob_day           INTEGER CHECK (dob_day BETWEEN 1 AND 31),
  tob               TEXT CHECK (tob IS NULL OR tob GLOB '[0-2][0-9]:[0-5][0-9]'),
  notes             TEXT NOT NULL DEFAULT '',
  birthday_reminder INTEGER NOT NULL DEFAULT 1 CHECK (birthday_reminder IN (0, 1)),   -- stored now, hidden in v1 UI
  created_at        INTEGER NOT NULL,
  updated_at        INTEGER NOT NULL,
  CHECK ((dob_month IS NULL) = (dob_day IS NULL))
) STRICT;
CREATE INDEX people_name ON people(first_name COLLATE NOCASE, last_name COLLATE NOCASE);

-- Phones, emails, addresses: any number of each, value + label ('personal', 'work', …)
CREATE TABLE person_contacts (
  id         TEXT PRIMARY KEY,
  person_id  TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('phone', 'email', 'address')),
  value      TEXT NOT NULL,
  label      TEXT NOT NULL DEFAULT '',
  position   INTEGER NOT NULL,           -- order within (person, kind); first = primary
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
CREATE INDEX person_contacts_person ON person_contacts(person_id, kind, position);

-------------------------------------------------------------------------------
-- 5. Task statuses (app-wide; Settings → Tasks). Default statuses have id = value.
-------------------------------------------------------------------------------
-- NOT_STARTED always first, DONE always last; defaults can be renamed, never deleted.
-- Reserved values (any case) can't be reused for custom statuses (checked in the app).
CREATE TABLE statuses (
  id         TEXT PRIMARY KEY,
  value      TEXT NOT NULL UNIQUE CHECK (value = upper(value) AND value GLOB '[A-Z]*'),
  label      TEXT NOT NULL UNIQUE COLLATE NOCASE,
  color      TEXT NOT NULL CHECK (color GLOB '#[0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F]'),
  position   INTEGER NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
  updated_at INTEGER NOT NULL
) STRICT;
INSERT INTO statuses (id, value, label, color, position, is_default, updated_at) VALUES
  ('NOT_STARTED', 'NOT_STARTED', 'Not started', '#7d8995', 0,    1, 0),
  ('IN_PROGRESS', 'IN_PROGRESS', 'In progress', '#1259d3', 1,    1, 0),
  ('DONE',        'DONE',        'Done',        '#1e7a55', 1000, 1, 0);

-- Defaults can't be deleted
CREATE TRIGGER statuses_keep_defaults BEFORE DELETE ON statuses
WHEN OLD.is_default = 1
BEGIN SELECT RAISE(ABORT, 'default status cannot be deleted'); END;

-------------------------------------------------------------------------------
-- 6. Task labels: a fixed list (Settings → Tasks); a task can carry several.
-------------------------------------------------------------------------------
CREATE TABLE task_labels (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE COLLATE NOCASE,
  color      TEXT NOT NULL CHECK (color GLOB '#[0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F]'),
  position   INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 7. Tasks
-------------------------------------------------------------------------------
-- Folders are identified by id; tasks point at their folder's path (renaming a folder rewrites
-- the paths below it, and tasks follow through ON UPDATE CASCADE). One root ('', id 'root'),
-- whose display name is settings tasks.root_name. Explorer sorts folders alphabetically.
CREATE TABLE task_folders (
  id         TEXT PRIMARY KEY,
  path       TEXT NOT NULL UNIQUE COLLATE NOCASE, -- '' (root), 'Work', 'Work/Infra'
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
INSERT INTO task_folders (id, path, created_at, updated_at) VALUES
  ('root', '', CAST(unixepoch('subsec') * 1000 AS INTEGER), CAST(unixepoch('subsec') * 1000 AS INTEGER));

CREATE TABLE tasks (
  id           TEXT PRIMARY KEY,
  path         TEXT NOT NULL REFERENCES task_folders(path) ON UPDATE CASCADE ON DELETE RESTRICT,
  parent_id    TEXT REFERENCES tasks(id) ON DELETE CASCADE,       -- subtask of … (one level)
  title        TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'NOT_STARTED'
               REFERENCES statuses(value) ON UPDATE CASCADE ON DELETE RESTRICT,   -- in use → can't delete
  description  TEXT NOT NULL DEFAULT '',                          -- markdown
  due_date     TEXT CHECK (due_date IS NULL OR due_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  due_time     TEXT CHECK (due_time IS NULL OR due_time GLOB '[0-2][0-9]:[0-5][0-9]'),
  assignee_id  TEXT REFERENCES people(id) ON DELETE SET NULL,
  order_key    TEXT NOT NULL,            -- one global fractional index (list, board, My day)
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  completed_at INTEGER                   -- set when status becomes DONE
) STRICT;
CREATE INDEX tasks_path     ON tasks(path);
CREATE INDEX tasks_parent   ON tasks(parent_id);
CREATE INDEX tasks_status   ON tasks(status);
CREATE INDEX tasks_due      ON tasks(due_date, due_time) WHERE due_date IS NOT NULL;
CREATE INDEX tasks_assignee ON tasks(assignee_id) WHERE assignee_id IS NOT NULL;
CREATE INDEX tasks_order    ON tasks(order_key);

-- My day: tasks due today are in by default; rows are manual overrides for a given day.
CREATE TABLE my_day (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  day        TEXT NOT NULL,              -- 'YYYY-MM-DD'
  included   INTEGER NOT NULL CHECK (included IN (0, 1)),
  updated_at INTEGER NOT NULL,
  UNIQUE (task_id, day)
) STRICT;

CREATE TABLE task_tags (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  tag_id     TEXT NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,
  updated_at INTEGER NOT NULL,
  UNIQUE (task_id, tag_id)
) STRICT;

CREATE TABLE task_label_links (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  label_id   TEXT NOT NULL REFERENCES task_labels(id) ON DELETE CASCADE,
  updated_at INTEGER NOT NULL,
  UNIQUE (task_id, label_id)
) STRICT;
CREATE INDEX task_label_links_label ON task_label_links (label_id);

CREATE TABLE task_comments (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  body       TEXT NOT NULL,              -- markdown
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL            -- later than created_at = edited
) STRICT;
CREATE INDEX task_comments_task ON task_comments(task_id, created_at);

-------------------------------------------------------------------------------
-- 8. Timers (local to the device)
-------------------------------------------------------------------------------
-- No background process. The window does the work:
--   create  → insert (title, ends_at, state 'running')
--   display → countdown = ends_at - now, recomputed every second
--   fire    → when now >= ends_at: desktop notification (+ sound), state = 'rung'
--   +1m / snooze → update ends_at;  cancel → state = 'cancelled'
--   on launch, running timers already past ends_at are shown once as "finished while closed"
CREATE TABLE timers (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL DEFAULT '',
  ends_at    INTEGER NOT NULL,
  state      TEXT NOT NULL DEFAULT 'running' CHECK (state IN ('running', 'rung', 'cancelled')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
CREATE INDEX timers_running ON timers(state, ends_at);

-------------------------------------------------------------------------------
-- 9. Feedback (local)
-------------------------------------------------------------------------------
CREATE TABLE feedback (
  id          TEXT PRIMARY KEY,
  kind        TEXT NOT NULL CHECK (kind IN ('bug', 'idea', 'other')),
  body        TEXT NOT NULL,
  app_version TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 10. Sync bookkeeping (local)
-------------------------------------------------------------------------------
-- Every delete of a synced row, including rows removed by ON DELETE CASCADE. Kept forever:
-- sync never brings a deleted row back.
CREATE TABLE deletions (
  id         INTEGER PRIMARY KEY,
  table_name TEXT NOT NULL,
  row_id     TEXT NOT NULL,
  deleted_at INTEGER NOT NULL,
  UNIQUE (table_name, row_id)
) STRICT;

-- Every write to a synced table, plus open / close / pull / push (written by the app).
-- Only the newest 10,000 rows are kept.
CREATE TABLE activity (
  id          INTEGER PRIMARY KEY,
  action      TEXT NOT NULL,             -- insert, update, delete, open, close, pull, push
  status      TEXT NOT NULL DEFAULT 'ok',
  entity_type TEXT,                      -- table name for writes
  entity_id   TEXT,
  at          INTEGER NOT NULL
) STRICT;

CREATE TRIGGER activity_cap AFTER INSERT ON activity WHEN NEW.id % 100 = 0 BEGIN
  DELETE FROM activity WHERE id <= NEW.id - 10000;
END;

-- deletions + activity for every synced table
CREATE TRIGGER settings_deleted AFTER DELETE ON settings BEGIN
  INSERT OR IGNORE INTO deletions (table_name, row_id, deleted_at) VALUES ('settings', OLD.id, CAST(unixepoch('subsec') * 1000 AS INTEGER));
  INSERT INTO activity (action, entity_type, entity_id, at) VALUES ('delete', 'settings', OLD.id, CAST(unixepoch('subsec') * 1000 AS INTEGER));
END;
CREATE TRIGGER settings_inserted AFTER INSERT ON settings BEGIN
  INSERT INTO activity (action, entity_type, entity_id, at) VALUES ('insert', 'settings', NEW.id, CAST(unixepoch('subsec') * 1000 AS INTEGER));
END;
CREATE TRIGGER settings_updated AFTER UPDATE ON settings BEGIN
  INSERT INTO activity (action, entity_type, entity_id, at) VALUES ('update', 'settings', NEW.id, CAST(unixepoch('subsec') * 1000 AS INTEGER));
END;

